// ─── File: OrchestrationDemo.java ───
// This file contains multiple classes for the runnable demo.
// In a real project each class would be in its own file.
package com.bank.orchestration;

import java.util.*;
import java.util.logging.*;

public class OrchestrationDemo {
    private static final Logger log = Logger.getLogger("Orchestration");

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        OrchestrationAdvisor advisor = new OrchestrationAdvisor();

        TeamProfile payments = new TeamProfile("payments-team",
                false /*needsPortability*/, false /*hasK8sExpertise*/, true /*avoidServers*/);
        TeamProfile platform = new TeamProfile("platform-team",
                true /*needsPortability*/, true /*hasK8sExpertise*/, true /*avoidServers*/);

        for (TeamProfile t : List.of(payments, platform)) {
            log.info(() -> t.name() + " orchestrator: " + advisor.chooseOrchestrator(t));
            log.info(() -> t.name() + " compute: " + advisor.chooseCompute(t));
        }
    }
}

// ─── Would be in OrchestrationAdvisor.java ───
class OrchestrationAdvisor {
    // EKS only when portability / Kubernetes ecosystem is genuinely needed.
    String chooseOrchestrator(TeamProfile t) {
        if (t.needsPortability() || t.hasK8sExpertise()) {
            return "EKS (managed Kubernetes: portable, large ecosystem, more complexity)";
        }
        return "ECS (AWS-native: simpler, deep AWS integration, no control plane to run)";
    }

    // Fargate removes server management; EC2 launch type only for special needs.
    String chooseCompute(TeamProfile t) {
        return t.avoidServers()
                ? "Fargate (serverless containers, no EC2 to provision/patch/scale)"
                : "EC2 launch type (manage instances for control/cost at high steady scale)";
    }
}

// ─── Would be in TeamProfile.java ───
class TeamProfile {
    private final String name;
    private final boolean needsPortability;
    private final boolean hasK8sExpertise;
    private final boolean avoidServers;
    TeamProfile(String name, boolean needsPortability, boolean hasK8sExpertise, boolean avoidServers) {
        this.name = name; this.needsPortability = needsPortability;
        this.hasK8sExpertise = hasK8sExpertise; this.avoidServers = avoidServers;
    }
    String name() { return name; }
    boolean needsPortability() { return needsPortability; }
    boolean hasK8sExpertise() { return hasK8sExpertise; }
    boolean avoidServers() { return avoidServers; }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                r.getMillis(), r.getLevel(), r.getMessage());
    }
}
